<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app';import { computed,ref } from 'vue';import { api } from '../../services/api';
const id=ref('');const notice=ref<any>(null);const recipients=ref<any>({items:[],summary:{counts:{}}});const working=ref(false);
const pendingIds=computed(()=>recipients.value.items.filter((i:any)=>i.recipientStatus!=='CONFIRMED').map((i:any)=>i.user.id));
async function load(){try{[notice.value,recipients.value]=await Promise.all([api(`/notices/${id.value}`),api(`/notices/${id.value}/recipients?pageSize=100`)]);}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
async function remind(){if(!pendingIds.value.length)return uni.showToast({title:'没有待催办人员',icon:'none'});working.value=true;try{await api(`/notices/${id.value}/reminders`,'POST',{targetUserIds:pendingIds.value,channels:['IN_APP'],note:'移动管理端人工催办'});uni.showToast({title:'催办已发送',icon:'success'});}catch(e:any){uni.showToast({title:e.message,icon:'none'});}finally{working.value=false;}}
async function close(){const ok=await new Promise<boolean>(r=>uni.showModal({title:'关闭通知',content:'关闭后停止新增提醒，历史记录仍保留。',success:v=>r(v.confirm)}));if(!ok)return;try{await api(`/notices/${id.value}/close`,'POST',{reason:'移动管理端关闭'});uni.showToast({title:'已关闭'});await load();}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
onLoad(q=>{id.value=String(q?.id??'');load();});
</script>
<template><view class="page"><view v-if="notice" class="card"><text class="title">{{notice.title}}</text><text class="muted">{{notice.status}} · 当前版本 {{notice.currentVersion}}</text><view class="metrics"><view><b>{{recipients.summary.total||0}}</b><text>有效接收</text></view><view><b>{{recipients.summary.counts?.CONFIRMED||0}}</b><text>已确认</text></view><view><b class="danger">{{pendingIds.length}}</b><text>待确认</text></view></view><view class="buttons"><button class="primary-btn" :loading="working" @tap="remind">催办待确认人员</button><button v-if="notice.status==='PUBLISHED'" class="secondary-btn" @tap="close">关闭</button></view></view><text class="section-title">人员明细</text><view v-for="r in recipients.items" :key="r.recipientId" class="card row"><view><text class="name">{{r.user.name}}</text><text class="muted">{{r.user.employeeNo}}</text></view><view class="right"><text :class="r.recipientStatus==='CONFIRMED'?'ok':'danger'">{{r.recipientStatus}}</text><text class="muted">{{r.confirmedAt?new Date(r.confirmedAt).toLocaleString():r.viewedAt?'已查看':'未查看'}}</text></view></view></view></template>
<style scoped>.title,.muted,.name,.right text{display:block}.title{margin-bottom:10rpx;font-size:34rpx;font-weight:800}.metrics{display:grid;grid-template-columns:repeat(3,1fr);margin:28rpx 0}.metrics view{text-align:center}.metrics b,.metrics text{display:block}.metrics b{color:#007f95;font-size:38rpx}.metrics text{color:#71868a;font-size:22rpx}.buttons{display:grid;grid-template-columns:2fr 1fr;gap:12rpx}.buttons button{font-size:24rpx}.row{display:flex;justify-content:space-between}.name{font-weight:700}.right{text-align:right}.ok{color:#168269}</style>
